def m(id, ch, title, trick, detail, tags=(), hy=True, lessons=()):
    d = {"id": id, "title": title, "chapterId": ch, "trick": trick, "detail": detail, "tags": list(tags), "highYield": hy}
    if lessons:
        d["lessonIds"] = list(lessons)
